begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('f0000000-0000-4000-8000-000000005430','setup-owner@example.test',now()),
 ('f0000000-0000-4000-8000-000000005431','setup-staff@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005430","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Weblink setup','weblink-setup-test',gen_random_uuid())::text,true);
select set_config('test.other',create_tenant('Other setup','weblink-setup-other',gen_random_uuid())::text,true);
select set_config('test.printer',gen_random_uuid()::text,true);
select is(register_weblink_printer(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,' Zebra ','ZD420',203),current_setting('test.printer')::uuid,'owner registers printer');
select is((select active from printers where id=current_setting('test.printer')::uuid),false,'setup never activates');
select is((select transport from printers where id=current_setting('test.printer')::uuid),'weblink','transport fixed');
select is((select address from printers where id=current_setting('test.printer')::uuid),'','no LAN address or credential');
select is(register_weblink_printer(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,'Zebra','ZD420',203),current_setting('test.printer')::uuid,'exact replay');
select is((select count(*) from access_events where tenant_id=current_setting('test.tenant')::uuid and action='printer.registered'),1::bigint,'one audit record');
select throws_like($$select register_weblink_printer(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,'Changed','ZD420',203)$$,'%REQUEST_CONFLICT%','changed replay refused');
select throws_like($$select register_weblink_printer(current_setting('test.other')::uuid,current_setting('test.printer')::uuid,'Zebra','ZD420',203)$$,'%REQUEST_CONFLICT%','cross-tenant id refused');
select throws_like($$select register_weblink_printer(current_setting('test.tenant')::uuid,gen_random_uuid(),'Zebra','ZD420',null)$$,'%INVALID_INPUT%','null DPI refused');
select throws_like($$select register_weblink_printer(current_setting('test.tenant')::uuid,gen_random_uuid(),' ','ZD420',203)$$,'%INVALID_INPUT%','blank name refused');
select throws_like($$select register_printer(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,'Zebra','tcp','192.0.2.1','ZD420',203,true)$$,'%PRINT_TRANSPORT_FIXED%','legacy API cannot activate Weblink');
select set_config('test.legacy',gen_random_uuid()::text,true);
select register_printer(current_setting('test.tenant')::uuid,current_setting('test.legacy')::uuid,'Legacy','tcp','192.0.2.1','',203);
select throws_like($$select register_weblink_printer(current_setting('test.tenant')::uuid,current_setting('test.legacy')::uuid,'Legacy','',203)$$,'%REQUEST_CONFLICT%','legacy printer cannot convert');
select throws_like($$select queue_print_job(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.printer')::uuid,'onboarding','zpl-v1','seller',gen_random_uuid(),'^XA^XZ',1)$$,'%PRINTER_INACTIVE%','inactive setup cannot queue output');
reset role;
insert into tenant_members(tenant_id,user_id,role) values(current_setting('test.tenant')::uuid,'f0000000-0000-4000-8000-000000005431','staff');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005431","role":"authenticated"}';
select throws_ok($$select register_weblink_printer(current_setting('test.tenant')::uuid,gen_random_uuid(),'Zebra','',203)$$,'42501',null,'staff cannot register');
reset role;
update tenant_members set role='admin' where user_id='f0000000-0000-4000-8000-000000005431';
set local role authenticated;
select lives_ok($$select register_weblink_printer(current_setting('test.tenant')::uuid,gen_random_uuid(),'Admin Zebra','',203)$$,'admin can register');
select throws_ok($$select register_weblink_printer(current_setting('test.other')::uuid,gen_random_uuid(),'Zebra','',203)$$,'42501',null,'non-member refused');
reset role;
set local role anon;
select throws_ok($$select register_weblink_printer(gen_random_uuid(),gen_random_uuid(),'Zebra','',203)$$,'42501',null,'anonymous refused');
reset role;
select * from finish();
rollback;
